insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 1, 'AFIESERE marches to 268.419002 s at an orifice of 1.250000 in and an end pressure of 145.000000 psia. Which part of that answer did the engine decide?', '["The end pressure, which the march carries down to its own choked floor of 26.758009 psia before it stops.", "The time step of 0.100000 s, which the march recomputes at every station from the mass it has left.", "None of it. The volume, both pressures, the gas properties, the orifice and the discharge coefficient are all stated, and the march returns what they demand.", "The discharge coefficient of 0.820000, which the march sets from the isentropic exponent the way it sets the gas coefficient C."]'::jsonb, 2, 'Every sizing route in this module takes its case as an input and the march is the same. It has no opinion about which end pressure matters, which vessel governs, or whether the orifice typed is the one on the drawing.'),
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 2, 'Every blowdown call returns the pressure below which its choked assumption stops holding, and on AFIESERE that is 26.758009 psia. What can be measured out of that figure alone?', '["The engine''s default outlet pressure: the floor times the engine''s own critical pressure ratio is 14.700000000000.", "The final temperature of 340.807983 degR, because the floor and the end state are both fixed by the pressure ratio and the exponent.", "The universal gas constant of 1545.349000000000, which this floor is the only route to since the march exports it nowhere.", "The end pressure of 145.000000 psia the march was asked for, because a march always stops a fixed ratio above its own floor."]'::jsonb, 0, 'Section 2 measures the same 14.700000000000 three separate ways and this is the third of them. Asking a routine a question whose answer is one constant and nothing else is how a figure it never exports gets measured.'),
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 3, 'Taken to an end pressure of 25.000000 psia the same call still succeeds, still returns a time, and attaches the engine''s choked-flow warning. Which way is that time wrong?', '["Conservative. Holding the choked assumption past the floor understates the rate, so the time returned is longer than the vessel would really take.", "Neither. The warning is about the final temperature of 232.011700 degR on that row, and the time is untouched by the assumption.", "Unreadable from the return. The warning names a condition without a direction, so the sign of the error has to be settled elsewhere.", "Optimistic. The march keeps assuming choked flow after the flow has stopped being choked, which overstates the rate and understates the time."]'::jsonb, 3, 'The engine''s own last word on that row is `optimistic`. A vessel that appears to empty faster than it does is the direction that makes a design look safer than it is, which is why the sign is worth reading off the message rather than guessing.'),
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 4, 'The march reports a starting inventory of 3469.2925 lb. Rearranged against the stated volume, pressure, temperature, molecular weight and compressibility, what is left over?', '["648.7449 lb, the inventory left at the end, because the mass balance closes on those same five stated inputs.", "1545.349000000000 ft.lbf per lbmol degR, the universal gas constant this march stands on and never exports.", "The gas coefficient C, which the mass flow uses and which the module computes from the isentropic exponent alone.", "The time step of 0.100000 s, because the march sizes its step from the inventory it starts the run with."]'::jsonb, 1, 'Nothing in the module exports that constant, so the start mass is the instrument that recovers it. A number you recovered is a number you can check, and a number you assumed will be wrong quietly.'),
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 5, 'A discharge coefficient of 0.600000 gives 366.839286 s and 1.000000 gives 220.103588 s. Those times are in a ratio of 1.666666542759 against a coefficient ratio of 1.666666666667. What does the gap measure?', '["The march''s own step error. The time runs inversely with the typed coefficient and nothing multiplies it.", "A second coefficient inside the mass flow, applied on top of the typed one, which this ratio is the only way to see.", "The compressibility drifting along the path, which these two runs are placed either side of on purpose.", "Rounding in the printed figures, since a blowdown time prints to six decimals and a ratio of two of them to twelve."]'::jsonb, 0, 'Two readings of one quantity. A caller''s figure used once and unmultiplied gives exactly this: agreement to about a part in a million, with the residue belonging to the integration rather than to the handling of the input.'),
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 6, 'The digest builds a closed-form time from the engine''s own gas coefficient, the recovered gas constant and the stated geometry, then prints the ratio of the marched time to it. What can that column catch?', '["A wrongly stated end pressure, because the closed form integrates between the two masses the caller asked for.", "An error in the thinning of the trajectory, since the closed form is assembled from the 270 stations the march returns.", "A discharge coefficient applied twice, a coefficient hidden inside the mass flow, or an isentropic exponent off by one.", "A compressibility drifting along the path, which the closed form allows to vary while the march holds it fixed."]'::jsonb, 2, 'All three faults move the answer smoothly across every case at once, which is the one pattern a sanity check cannot see. A constant factor is invisible on a number and visible only against a second derivation of the same quantity.'),
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 7, 'AFIESERE took 2685 steps at a step of 0.100000 s and returned 270 stations. What do those three counts say together?', '["The march subdivided its way from 270 planned steps up to 2685 taken ones, which is what the returned counts exist to record.", "The trajectory is thinned before it is handed back, to about one station a second here, and the step size and step count are returned so the thinning cannot mislead.", "The 270 stations are the steps that advanced the clock and the rest were rejected by the inventory budget and retaken.", "The step was chosen to place one station a second, so the station count follows from it and a finer step returns more stations."]'::jsonb, 1, '2685 steps thinned to 270 stations is coarser than the march that produced it and fine enough to draw a curve with. Read what a route says about how it ran before you read what it returned.'),
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 8, 'Across all 270 AFIESERE stations the temperature falls from 545.000000 degR to 340.807983 degR and never turns. What is doing that?', '["The gas leaving through the orifice carries enthalpy out with it, and the reported temperature is what the inventory has left after that loss.", "The gas throttles across the orifice, and the temperature each station carries is the throat temperature at that moment.", "The compressibility falls away as the pressure drops, and the temperature the march prints follows it down.", "The gas left behind expands to fill the same volume at a lower pressure, and this march gives the vessel no heat in from the metal or the surroundings."]'::jsonb, 3, 'The march takes the expansion as isentropic at the stated exponent and holds the compressibility constant at the stated value. Both are decisions rather than results, and the audit module names them as such.'),
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 9, 'AFIESERE returns 3469.2925 lb and 648.7449 lb, and the digest prints 0.813004 beside them. Which question does 0.813004 answer?', '["How much of the starting inventory left, as a share of it.", "How far the pressure fell, as 145.000000 psia over the 1240.000000 psia the vessel started at.", "How much of the march ran above the choked floor of 26.758009 psia before the warning would have fired.", "How much of the time limit of 7199.999985603571 s the run used up before it reached its end pressure."]'::jsonb, 0, 'It is derived rather than returned: the two masses the march reports at the ends, differenced and divided. The stations themselves carry no mass at all, so an inventory profile is not a thing this call can be read for.'),
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 10, 'The march holds the compressibility constant along the path and assumes choked flow throughout. What does the validation oracle do about those two decisions?', '["It relaxes both and integrates the real expansion, so the published difference between the two is the cost of the assumptions.", "It refuses the rows where either assumption is crossed, which is why the published block carries 5 rows rather than 7.", "It makes both of them deliberately, so that what the published set checks is the march rather than the thermodynamics.", "It keeps the choked half and lets the compressibility vary, which is what the published relative difference of 1.062e-3 measures."]'::jsonb, 2, 'A shared assumption narrows what a comparison can tell you, and saying so is the honest handling. The engine also names the pressure below which the choked half stops holding, so the assumption that can bite a particular run is readable off that run.'),
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 11, 'At a 2.0 in orifice the march returns 104.851242 s and the closed form of the same balance gives 104.851161 s, a ratio of 0.999999232099. What is that pair evidence for?', '["That the closed form is the better of the two answers, and the march is quoted only because it returns a curve as well.", "That the exponent the march uses agrees with the one the published blowdown rows were generated at.", "That the orifice area enters the rate linearly, since the ratio holds across all four of the cases printed.", "That the march reproduces the exact integral of its own balance, with the residue being integration error."]'::jsonb, 3, 'The separable mass balance is what makes the closed form available: the rate of mass loss goes as the mass raised to (k+1)/2, so the time between two masses integrates exactly. This check and a convergence study answer different questions.'),
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 12, 'While the flow through the blowdown orifice is choked, the downstream pressure does not reach back through the throat to change the rate. What does that buy the march?', '["Freedom from the back pressure entirely, since no field the call returns depends on what the header is at.", "One state variable, one rate and one step, because the rate is set by the upstream state and the throat alone.", "An end pressure that stops mattering, so the march runs down to the choked floor of 26.758009 psia on every case.", "A discharge coefficient that absorbs the downstream condition, which is why a typed coefficient moves the time."]'::jsonb, 1, 'It is the same result the Associate tier met on the valve, where the required area in critical flow did not move with the back pressure at the relief valve outlet at all. Here it also earns the march an assumption, which the engine states rather than hides.'),
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 13, 'You are handed a blowdown result and asked whether its flow assumption held over the run. Which returned field settles that, and against what?', '["The count of steps that had to be subdivided, which goes above zero exactly when the march crosses that floor.", "The final temperature, because an end state below the floor no longer follows the isentropic relation.", "The pressure below which the choked assumption stops holding, read against the end pressure you asked for.", "The step size the march used, because the step budget is written against the choked assumption."]'::jsonb, 2, 'On AFIESERE the floor is 26.758009 psia against an end pressure of 145.000000 psia, and the warning field reads `null`. An answer taken well above the returned floor, with the warning read first, does not rest on that assumption at all.'),
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 14, 'Which of these AFIESERE figures is something the march worked out rather than something the caller stated?', '["The starting inventory of 3469.2925 lb.", "The vessel volume of 720.000000 ft3.", "The compressibility of 0.880000.", "The orifice of 1.250000 in."]'::jsonb, 0, 'The stated case is the volume, both pressures, the temperature, the molecular weight, the isentropic exponent, the compressibility, the orifice and the discharge coefficient. The inventory is the first thing the march builds from them.'),
  ('relief', 'advanced', 'module', 'm01-a-vessel-emptying-itself', 15, 'The digest prints 4.473650 min and -118.862017 degF on the AFIESERE row and marks both as derived. What does that label mean here?', '["The engine returned both, and the label records only which of its fields carry a unit at all.", "Both came from the closed form rather than from the march, and are printed beside the marched figures for comparison.", "Both were read off the last station of the trajectory rather than off the top-level fields of the return.", "The engine returned a time in s and a temperature in degR, and the digest converted each into a second unit."]'::jsonb, 3, 'A derived figure is arithmetic on an engine return and the digest says so. What the engine handed back is 268.419002 s and 340.807983 degR, and those are the figures an answer should be recorded at.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 1, 'A depressuring study is run to ask whether a vessel is down inside the customary fifteen minutes. What does this engine hold about that figure?', '["It holds it as the limit the march refuses at, which the digest bisects out at 7199.999985603571 s.", "Nothing at all. There is no constant for it, no returned flag and no verdict of any kind.", "It holds it as a warning edge, so a run past 900.000000 s returns a note.", "It holds it as the default stopping point of a march, so a call with no end pressure stated runs to fifteen minutes."]'::jsonb, 1, 'The march returns 268.419002 s on AFIESERE, which is 4.473650 min, and stops there. Comparing that against a limit is your act, on a limit you stated, for a case you chose.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 2, 'One time limit does live inside this route, bisected out of the engine''s own behaviour at 7199.999985603571 s. What kind of statement does it make?', '["A verdict about the design, since a vessel that cannot empty inside it has failed its depressuring case.", "A warning on a successful answer, so the time still comes back and carries a note beside it.", "A ceiling on the trajectory, past which the march returns the stations it has and adds no more.", "A refusal about the computation, carrying `error` and naming the input most likely to be at fault."]'::jsonb, 3, 'The message is `did not reach the end pressure inside the time limit: check the orifice size`. That limit and the customary target are easy to confuse: one is an engineering criterion you supply and the other an internal budget past which this implementation will not go.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 3, 'Doubling the orifice from 1.000000 in to 2.000000 in takes the time from 419.404662 s to 104.851242 s, a ratio of 0.250000182473. What does that say the time runs with?', '["The area of the hole, since the mass rate through a choked throat goes with the throat area.", "The diameter of the hole, which the two rows quoted show halving the time as the diameter doubles.", "The cube of the diameter, which is what the printed ratio works out to across a doubling.", "The pressure ratio, which the orifice moves by the same factor that it moves the clock."]'::jsonb, 0, 'That is the only ratio the digest computes anywhere on this sweep, which is why it is the only one you may quote from it. Every ratio you form yourself down a printed table is a figure nothing stands behind.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 4, 'The substep column reads 0 on every row of the orifice sweep, from 0.500000 in through to 3.000000 in. What is that column a statement about?', '["The orifice, since an orifice inside the swept range never needs a step subdivided.", "The choked assumption, since subdividing is what the march does as it crosses its own floor.", "The step size against these geometries, since no step here would have removed more than a twentieth of the inventory.", "Convergence, since a march that has converged subdivides nothing by definition."]'::jsonb, 2, 'At the same step size the small-vessel and large-orifice cases in the next module subdivide every step they take. The column is about what a fixed step has to work with rather than about the orifice on its own.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 5, 'The design question runs backwards: which orifice meets a stated time. The engine has no route for it. How does the digest fill that gap, and why that way?', '["By rearranging the closed form of the march for the diameter, since that closed form and the marched time agree to about a part in a million anyway.", "By interpolating between the sweep rows at 0.500000 in and at 0.750000 in, since the time falls monotonically right across that whole interval.", "By selecting from the published ladder, since a blowdown restriction comes off the same 14 standard areas.", "By bisecting on the engine''s own returned time, because that answers the question about the engine rather than about a formula beside it."]'::jsonb, 3, 'The answer is defined as a diameter at which the engine returned the target, so anything a rearrangement could have got wrong is now impossible to get wrong. A solve against the engine and algebra beside it are different kinds of claim.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 6, 'The bisected answer is 0.682646 in, where the march returns 900.000000 s. Which two rows of the sweep show the answer had to lie where it did?', '["0.750000 in at 745.608268 s and 1.000000 in at 419.404662 s, the two rows nearest the target in time.", "0.500000 in at 1677.618587 s and 0.750000 in at 745.608268 s, which straddle the target.", "1.250000 in at 268.419002 s and 1.500000 in at 186.402100 s, the rows the stated AFIESERE case sits between.", "0.500000 in at 1677.618587 s and 0.682646 in at 900.000000 s, the bracket the bisection finally closed on."]'::jsonb, 1, 'A bisection needs its answer inside its bracket and cannot tell you when it is not. Reading the result back against the sweep is the cheap confirmation that it was.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 7, 'Across eight orifices the final temperature column reads 340.807983 degR on every row, and the digest counts the distinct values at 1. Why is the count worth more than the column?', '["It proves the temperature right, since eight runs agreed on it.", "It shows the march converged, since one end state comes back whatever the step.", "It turns a plausible claim about the model into a measurement made on the engine.", "It shows the step was fine enough, since a coarse step would spread the column."]'::jsonb, 2, 'Somebody could assert that the end state is independent of the orifice and it would sound like a fair claim about a model. The sweep is what makes it a reading instead.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 8, 'What is the AFIESERE final temperature of 340.807983 degR fixed by?', '["The pressure ratio across the blowdown and the isentropic exponent.", "The orifice and the discharge coefficient, which together set how fast the expansion happens.", "The start temperature of 545.000000 degR and the 268.419002 s the march took to get down.", "The choked floor of 26.758009 psia, which is the coldest state this march can reach."]'::jsonb, 0, 'The orifice decides only how long the vessel takes to get there, which is harder to hold than it looks because the orifice is the one thing a designer can change. What does move the end state is the end pressure, and the digest walks seven of them.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 9, 'Taken to 600.000000 psia the vessel finishes at 464.976597 degR with 0.432854 of the inventory gone; taken to 25.000000 psia it finishes at 232.011700 degR with 0.952641 gone. What may be said about that table?', '["That the final temperature falls in proportion to the end pressure the march was given, which those two rows are enough on their own to establish.", "That the fraction removed and the final temperature move together, so either may be quoted in place of the other.", "That the time runs with the inventory removed, since the two columns rise together all the way down.", "The directions only. A deeper blowdown runs longer, ends colder and removes more, and no ratio between any pair is printed."]'::jsonb, 3, 'Both figures in any quotient you form are real engine output, and that does not make the quotient anything. Ask first whether two quantities are entitled to be compared, and only then compare them.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 10, 'The bottom row of the end-pressure table, at 25.000000 psia, crosses the choked floor of 26.758009 psia and carries the engine''s warning. Which figure on that row does the warning bear on?', '["Both of them, since a run taken past the floor is no longer the model that either of the two figures on the row came from.", "The final temperature, since the choked assumption is what carries the expansion going on inside the vessel all the way down.", "The time of 540.397236 s, which it names, while 232.011700 degR is still the end state for that pressure ratio.", "The fraction removed of 0.952641, since the mass leaving is what the choked assumption governs."]'::jsonb, 2, 'Read a warning for its scope as much as for its direction. This one says the time below the floor is optimistic and says nothing else, so the reading to discount is the clock.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 11, 'Down the orifice sweep the step count falls from 16777 at 0.500000 in to 467 at 3.000000 in. What explains that?', '["The step size is held fixed across the sweep, so a shorter march needs fewer steps.", "A larger orifice lets the march take longer steps.", "The march thins a short run harder, and the count follows the stations.", "The inventory budget bites at small orifices, so the extra steps are subdivided."]'::jsonb, 0, 'The step is 0.100000 s on every row, so the count is the clock divided by it. The substep column stays at 0 throughout, so not one of those steps is a subdivided one.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 12, 'What is 0.682646 in a property of?', '["The vessel, since the orifice that empties it in a stated time is fixed once the volume and the two pressures are.", "This march on this vessel, at these gas properties, this discharge coefficient and this step size, reaching 145.000000 psia in 900.000000 s.", "The standard ladder, since it is the area below which a blowdown restriction has to be doubled up.", "The closed form, since the digest solved that integral for the diameter that lands on 900.000000 s."]'::jsonb, 1, 'It is not an orifice anybody can buy, and turning it into hardware is a separate step. The API 526 ladder the Associate tier worked through is a table for pressure relief valves rather than for blowdown restrictions.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 13, 'This module treats a time, an orifice and a final temperature as three different kinds of object. Which grouping is the module''s?', '["A time is a solve, an orifice is a reading and a temperature is an input to both.", "All three are outputs of one call, which is why the sweep prints all three on one row.", "A time and a temperature are readings, and the orifice is the input.", "A time is a reading, an orifice is a solve and a temperature is a consequence."]'::jsonb, 3, 'Treating all three as outputs of one call is how a reader ends up quoting the one the engine was least asked about. The temperature is the clearest case, since the orifice sweep never tested it at all.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 14, 'A colleague quotes 268.419002 s as the depressuring time for this vessel. What has that figure silently brought with it?', '["Every input that run was given, down to the step size the march happened to be called with.", "An acceptance criterion of some kind, since a time comes back only for a run that the engine has judged to have passed.", "A trimmed clock, since the time that comes back covers only the part of the march over which the flow was actually choked.", "A tolerance of its own, since the march reports a time only to the precision that its own step size is able to support."]'::jsonb, 0, 'Move any one of them and the whole curve moves, so the curve is a property of the vessel and the assumptions together. That is why a study quotes both, and why a time on its own looks exactly like a fact about the vessel.'),
  ('relief', 'advanced', 'module', 'm02-the-customary-depressuring-time', 15, 'What does this module ask you to write down beside a depressuring time, and why?', '["The step count and the station count, because the customary fifteen-minute judgement is the one that gets made on those two.", "The orifice that would have bought exactly fifteen minutes, because the comparison is made against that.", "The limit you are judging against and where it came from, because the engine records no criterion of its own.", "The final temperature, because the customary time is stated for the end state rather than for the clock."]'::jsonb, 2, 'A bare time in a report looks exactly like a passing time. The engine holds no fifteen minutes, so the criterion and its source are yours to carry.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 1, 'Halving the step seven times takes the AFIESERE time from 268.420990 s at 0.800000 s to 268.418974 s at 0.012500 s, a total movement of 0.002015907907 s. What does that movement establish?', '["That the march converges in its own terms, with the step still visible in the sixth decimal a time prints at.", "That the march is converging on the right balance to be marching, since the sequence settles down rather than wandering.", "That the default step of 0.100000 s is the coarsest one this vessel tolerates before the answer moves.", "That the remaining error in the time is 0.002015907907 s, which is the figure an answer carries as its uncertainty."]'::jsonb, 0, 'It establishes convergence in the march''s own terms and nothing more. The movement is 4031.815814 times half a unit in the sixth decimal, so the step shows in a printed time and is stated beside it. A march converging beautifully to a wrong answer is a thing numerical methods do very well, and the check for that is the closed-form comparison in the first module.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 2, 'The refinement halves the step over a contiguous sequence of seven values rather than sampling a few. Why does the contiguity matter?', '["A gap would leave the step counts unable to double, so the relationship between them could not be read.", "The engine subdivides a step that skips a decade, so a sparse sequence returns substeps and stops comparing like with like.", "A table with a gap in it invites a reader to assume the behaviour across the gap, which is the thing a convergence table exists to stop.", "The ratio against the finest step is only defined where every intermediate step was also run."]'::jsonb, 2, 'Contiguity is part of the method rather than a presentational choice. The whole sixty-four-fold refinement is there so the reader can watch, and a reader who has to interpolate is back to assuming.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 3, 'A study refines a step and a comparison runs the same balance in closed form. What does each one establish that the other cannot?', '["Refinement checks the balance being marched and the closed form checks the arithmetic underneath it, which is why the ratio column reads one.", "Refinement says whether you have walked far enough down one road; the closed form says whether it is the road you meant to be on.", "Refinement checks the time and the closed form checks the final temperature, which is the one column that refinement is unable to move at all.", "Refinement checks the engine and the closed form checks the published cases, which are generated from it."]'::jsonb, 1, 'The two answer different questions and a march needs both. The closed-form ratios in the first module sit within a part in a million of one, and the refinement here moves the time by 0.000007510303 of itself.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 4, 'The final temperature column reads 340.807983 degR on all seven rows of the refinement study. What has the study told you about that figure?', '["That it has converged the most tightly of the three columns, since it did not move at all.", "That the end state is a stronger result than the time, since it is stable under a sixty-four-fold refinement.", "That the step size is fine enough for the temperature even where it would be too coarse for the time.", "Nothing. Refinement cannot move it, so the study left it alone rather than validating it."]'::jsonb, 3, 'The end state is fixed by the pressure ratio across the blowdown and by the isentropic exponent, and neither is a function of the step. Reading a constant column as confirmation is reading an absence of evidence as evidence.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 5, 'AFIESERE finishes at 145.000000000000 psia against a target of 145.000000 psia, a difference of -0.000000000000 psia. What does that show about the march?', '["It rounds the final pressure to the target once the step that crossed it has been taken.", "It chose a step size that divides the pressure drop into a whole number of increments.", "It lands on the end pressure rather than reporting the time of the step that crossed it.", "It reports the target back rather than the pressure it actually reached, at full precision."]'::jsonb, 2, 'Reporting the step that crossed the target quantises the answer to one step, which on a coarse step is a real error and on any step is a needless one. Comparing the final pressure returned against the pressure asked for, at full precision, is the check on any march.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 6, 'A small vessel through a large orifice can lose more mass in one step than it holds. What does this march do about that, and what does it tell you afterwards?', '["It subdivides any step that would remove more than a twentieth of the inventory, and returns how many it subdivided.", "It refuses the geometry and names the orifice, because an explicit march has nothing to offer there.", "It falls back on the closed form for the first step and rejoins the march once the inventory allows it.", "It shortens the run to the part of the march the step size can carry, and warns that the time is optimistic."]'::jsonb, 0, 'At the stated step AFIESERE subdivided 0 of its 2685 steps, so the count is zero when the budget never bites. It is not a fault when it is non-zero: it says the geometry sits in the corner where a fixed step struggles.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 7, 'The three hard cases, 5.000000 ft3 through 4.000000 in, 100.000000 ft3 through 17.000000 in and 500.000000 ft3 through 38.000000 in, each report 34 steps and 34 substeps. What is the substep column saying?', '["34 extra steps were inserted beyond the 34 the march had planned on taking, which doubles the work on each of the three rows.", "34 steps were rejected and retaken at a finer step size chosen from the vessel volume.", "The march subdivided until the step matched the finest one in the refinement study, which took 34 passes.", "Every step in all three runs had to be cut, which is why each reaches its end pressure with a time above zero."]'::jsonb, 3, 'These are the geometries where a fixed step has the least to work with, and they are in the study on purpose. Without the budget the first step would take out more mass than the vessel holds.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 8, 'Why do three geometries nobody would design belong in a published validation set?', '["They are the cases the closed form cannot reach, so only a march can generate a published answer for them.", "A typical case checks that the arithmetic runs; an extreme one checks that the method holds.", "They exercise the shortest times in the set, which is where the relative difference against the oracle is largest.", "They are where the choked assumption is nearest its floor, so they are the rows that carry the engine''s warning."]'::jsonb, 1, '2 of the 5 published blowdown rows use an orifice of 4 in or larger and 1 sits at 10 ft3 or smaller. A set of sensible vessels through sensible orifices cannot tell a march that works from a march that stops before it starts.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 9, 'A time step of zero and a negative time step both come back as refusals rather than as warnings. Why is a refusal the only honest handling?', '["A negative step would march the pressure upward, and the engine has no branch for a vessel filling.", "A zero step divides the inventory budget by zero, so the first subdivision is undefined and the run aborts.", "A march whose clock never advances can never reach its own time limit, so it would spin against a budget it cannot exhaust.", "The step is an accounting field, and a wrong one invalidates the answer."]'::jsonb, 2, 'The message on both is `the time step must be a finite number above zero`. The third refusal in that family is the time limit itself at 7199.999985603571 s, which names the orifice as the likely cause.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 10, 'Each row of the refinement study carries a ratio in its last column, and the digest computes nothing between rows. What follows for a reader?', '["The column can be read downward as a rate of convergence, since each entry is the previous one halved.", "The ratios may be divided into each other to recover the order of the method.", "The column means something only at the finest step, where the ratio reaches 1.000000000000.", "Any statement about how the column behaves is a reading you take rather than a figure you were handed."]'::jsonb, 3, 'Each entry is that row''s time over the time at the finest step. Take the reading deliberately and say you took it, which is a different act from quoting a figure the digest computed.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 11, 'The step count runs 336 at 0.800000 s, 2685 at 0.100000 s and 21474 at 0.012500 s. What is that column recording?', '["A fixed step on a fixed march, so the count roughly doubles each time the step is halved.", "The march choosing more steps as it refines, since a finer step needs a longer run to reach the end pressure.", "The number of stations returned at each step size, which is what the trajectory is thinned down to.", "The steps plus the subdivided ones, which is why the count grows faster than the step shrinks."]'::jsonb, 0, 'The substep column is 0 on every row of this study, so nothing here needed subdividing and the count is the clock divided by the step. The final temperature is identical on all seven rows for a separate reason.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 12, 'Before quoting any march result, this module asks four questions in order. Which order is the module''s?', '["Is the warning empty, did it converge, was the oracle independent, and does the published set cover it.", "Did it get there, was the step fine enough, was anything subdivided, and is the warning field empty.", "Was the step fine enough, did it get there, is the time inside the customary limit, and was it choked.", "Did it get there, was the case the governing one, was the step fine enough, and is the answer plausible."]'::jsonb, 1, 'The accounting fields exist so that the first three can be answered off the return itself. A time read off a march whose warning you did not look at is a time you are guessing about.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 13, 'The march holds a time and a final temperature, and they need different instruments. Which pairing is right?', '["The time is algebraic and the closed form checks it; the temperature is an integral and refinement checks it.", "Both accumulate step by step, so refinement is the instrument for each of them and the published rows confirm it.", "Both are algebraic consequences of the two pressures, so neither is touched by the step and refinement checks neither.", "The time is an integral and refinement suits it; the temperature is algebraic and an independent statement is what checks it."]'::jsonb, 3, 'The time can be wrong by a little at every step, which is what a refinement study is for. The temperature follows from two pressures and an exponent, and what checks it is the published final temperature sitting beside the published time on every one of the 5 blowdown rows.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 14, 'The three hard geometries differ in volume by two orders and in orifice by nearly ten times, yet all three finish at 114.700000 psia and 338.611469 degR. Why?', '["They were all subdivided to the same step, so the three marches were effectively the same run.", "They each removed the same fraction of their inventory, which fixes the end state whatever the vessel holds.", "They were given the same two pressures and the same exponent, and the end state follows from those alone.", "The end state is clamped at the choked floor, which the three share because they share a back pressure."]'::jsonb, 2, 'Geometry decides the clock and the two pressures decide the cold end. The times on those rows are 0.167677 s, 0.185663 s and 0.185791 s, and they are the only column of the three that the geometry moved.'),
  ('relief', 'advanced', 'module', 'm03-a-step-size-is-an-answer', 15, 'What does a march owe a reader that a closed form does not?', '["An account of how it ran, because a march cannot be read the way a closed form can.", "A trajectory, because an integration has intermediate states and a closed form has none to report.", "A warning field, because only an iterative method can reach a condition its inputs did not declare.", "A refusal on a bad step size, which a closed form never takes."]'::jsonb, 0, 'Six of the eleven returned fields are the answer, four are the account and the eleventh is the warning slot. A march that returned a time alone would be asking you to accept its step size, its stopping rule and its flow assumption on trust.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 1, 'The solid angle in the point-source relation is not exported, and the digest recovers 12.566370614359 from one returned intensity against its own stated inputs. Which class does that figure fall into?', '["Typed, because the value is a published geometric constant that the engine takes as an input and names.", "Held for literature, because nothing here can derive it.", "A stated convention of this engine, pinned by the suite so that it cannot move without somebody noticing.", "Computed, because the oracle reaches the same figure by quadrature of the sphere area."]'::jsonb, 3, 'It is one of the constants in this module that something actually checks. Measuring it out of behaviour is what made it visible at all, since the engine keeps it inside the relation.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 2, 'The AFIESERE flare is stated as 210000.0000 lb/hr at 19400.0000 Btu/lb, and the digest derives a heat release of 1193971.5392 kW. Who owns that derivation?', '["The engine, which converts the rate and the heating value on the way into the intensity relation.", "The caller. The engine takes a heat release in kW and knows nothing about rates or heating values.", "The oracle, which carries the unit packaging so the engine can work in kW throughout.", "The digest alone, since the engine refuses a release stated in any unit other than Btu/hr."]'::jsonb, 1, 'The mass rate and the heating value are the caller''s arithmetic and the caller owns any error in them. Stating a release in kW is also how a capstone answer stays clear of a conversion nobody graded.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 3, 'At 40.000000 m the intensity is 17.482435 kW/m2 and at 80.000000 m it is 4.370609 kW/m2. Which comparison does the digest invite you to make on those rows?', '["The ratio of the two intensities against the ratio of the distances themselves.", "The difference of the intensities against the difference of the distances.", "The ratio of the two intensities against the ratio of the squared distances.", "The ratio of the two intensities against the ratio of the radiated fractions behind them."]'::jsonb, 2, 'The intensity falls with the square of the distance, and this is the one place in the course where you are invited to form a ratio of your own, because the relation is exact and stated. Take it on a pair of rows of your choosing and watch the two ratios meet.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 4, 'The forward route gives 0.795774715459 kW/m2 at 10.000000 m, and the inverse hands back 10.000000000000 m for that intensity, a ratio of 1.000000000000. What has that established?', '["That the two implementations agree.", "That the point-source model is sound in both of the directions it is asked in.", "That the solid angle of 12.566370614359 is the correct one for a sphere.", "That the transmissivity is applied once rather than twice on either side."]'::jsonb, 0, 'A round trip through a function and its own inverse is an identity. Exactness here is the least informative outcome available, and a suite showing only this would be showing you nothing.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 5, 'Which of these faults would still close that round trip perfectly?', '["A radiated fraction outside its range, since both directions validate that input identically.", "A wrong solid angle, an inverse-cube law, or a transmissivity applied twice.", "An error in the stated flare rate, since the release is derived first.", "A difference in printing precision between the two routes."]'::jsonb, 1, 'The same error is applied and then removed, so the trip closes whatever it was. What makes the model itself checked is the oracle deriving the sphere area by quadrature and the inverse by bisection on that same quadrature.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 6, 'What is the difference between a second implementation of a relation and a different derivation of the same quantity?', '["A second implementation checks the inputs; a different derivation checks the units they arrive in.", "A second implementation is what an oracle is; a different derivation is what a published case is.", "A second implementation checks the forward route; a different derivation checks only the inverse.", "A second implementation checks a transcription; a different derivation checks the relation."]'::jsonb, 3, 'When somebody shows you agreement, the question is how far apart the two sides were to begin with rather than how close they came. That question is the one this whole module is circling.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 7, 'Both radiation directions refuse a radiated fraction of zero, a transmissivity above one and a negative transmissivity. Why is checking that symmetry worth the trouble?', '["An inverse bolted on later commonly validates less than the forward route, so a value the forward one would have refused sails through it.", "The inverse solves by bisection, so an unvalidated input can put its bracket the wrong way round.", "The two routes share their validation code, so a difference between them would be a packaging fault.", "An inverse that refuses more than its forward route would make the round trip fail to close."]'::jsonb, 0, 'It is a cheap test with a real failure mode behind it. The audit module runs every one of those refusals, and both directions take the same four inputs.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 8, 'The stated flare at a radiated fraction of 0.320000 and a transmissivity of 0.920000 gives 1.427138 kW/m2, and at 0.320000 and 1.000000 it gives 1.551237 kW/m2. What are those two inputs?', '["Published constants for a hydrocarbon flare, typed into the call with their reference named the way Kb and KSH both are.", "Held-for-literature values, taught as stated limits and deliberately kept out of everything this course puts a mark on.", "Project figures, typed and validated as fractions, which nothing in the package derives and nothing should.", "Computed figures, since the engine derives both from the heat release and the distance it is given."]'::jsonb, 2, 'The audit column reads TYPED inputs, and the reason given is that they are project figures. That is a different status from a chart value carrying a reference and different again from a figure nothing can derive.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 9, 'You have an intensity relation and a route that returns a distance. Why does this course compute no flare setback?', '["A setback needs a flame height, which this engine has no route for and the digest never prints.", "The four customary intensities are held for literature, so no distance solved against one may be reported.", "The point source is a screening model, and a setback has to come from a solid-flame model instead.", "The setback, the pool fire behind it and the customary allowable intensities are owned by a merged sibling course."]'::jsonb, 3, 'That course computes a setback, does the pool fire and the flame height beside it, teaches the limitations of the point source, and grades a setback in its own Professional capstone. This module hands the question back by name.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 10, 'A test asserts that the relief engine''s allowable-intensity table and the spacing engine''s stay equal, row by row and wording included. What does it establish?', '["That the two copies have not drifted apart, so changing one becomes a reviewed act rather than a quiet one.", "That the four values are correct, since two engines derived them separately and agree.", "That the wording is sourced, since a label asserted against a second copy carries that copy''s reference.", "That either table may be read as an answer, since a pinned table cannot be wrong without the suite going red."]'::jsonb, 0, 'Both tables could carry the same wrong value and the same misleading label and the test would pass forever, because it compares them to each other and to nothing else. A check compares a quantity against something derived independently of it; a pin fixes a quantity so it cannot move unnoticed.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 11, 'The four customary intensities are 1.580000, 4.730000, 6.310000 and 9.460000 kW/m2, each with a label. Who wrote the labels, and what follows?', '["API 521 wrote them, so a distance quoted against one inherits the standard''s authority.", "The spacing engine wrote them and this one copied them.", "This package wrote them, so they are an interpretation with no source attached here.", "The validation oracle wrote them, which is why a test can assert the two tables stay equal."]'::jsonb, 2, 'A label carries more authority than a bare number because it sounds like a finding. Nothing graded in this course reads a row of that table, and the honest use is to cite it as customary and name it as unsourced here.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 12, 'A distance comes back from the inverse route. What has to be recorded with it for the answer to be auditable?', '["The exposure category the allowable was read from, so a reader can find the row you used.", "The allowable intensity you solved against and where it came from.", "The heat release in Btu/hr, so a reader can check the conversion the engine performed.", "The transmissivity and the radiated fraction, because those are the two figures the equality test pins."]'::jsonb, 1, 'A distance beside a stated allowable is auditable, because a reader can disagree with the allowable without reverse-engineering which row of a table you used. A distance beside a named exposure category is not.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 13, 'The blowdown march returns eleven fields and the intensity route returns one. What is that contrast about?', '["How much each route was validated, since the oracle checks the march in closed form and the point source by quadrature.", "How much each route can refuse, since the march runs four refusals and the point source only three.", "How much each route costs to call, since a march returns its trajectory and a relation returns a scalar.", "How much each route had to decide. The march integrates and owes an account; the point source evaluates one relation."]'::jsonb, 3, 'The size of a return is a statement about how much the route had to decide. Nothing in the point-source call has a step size, a stopping rule or a flow assumption for a reader to audit.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 14, 'The published radiation and setback rows agree with the engine at relative differences around 5.116e-15 and 2.588e-15. Why is that the expected outcome here?', '["The oracle finds the sphere area by quadrature and the inverse by bisection on it, so two different pieces of arithmetic meet at the same sphere.", "Both sides evaluate the same closed form, so anything above floating-point rounding would be a packaging error.", "The published rows were generated from the engine, so the only difference available is the printing precision.", "The relation carries no iteration, so the agreement is limited only by the six decimals an intensity prints at."]'::jsonb, 0, 'Those differences are at the size of floating-point rounding and on this route that is a good result. On the blowdown block the agreement is looser and the looser one is the stronger result, which is the subject of the audit module.'),
  ('relief', 'advanced', 'module', 'm04-the-point-source-twice', 15, 'A layout decision needs the distance at which a stated allowable is met. Which two figures does the inverse route need beside that allowable?', '["A distance to start its bracket from, and the radiated fraction the bisection is to close on.", "A relief rate in lb/hr and a lower heating value in Btu/lb, which it converts internally.", "A heat release in kW, and the radiated fraction and transmissivity it is to be applied at.", "A flame height and a radiated fraction, which place the source above grade."]'::jsonb, 2, 'It takes the same four inputs as the forward direction and refuses the same bad ones. What it returns is one field, the distance in m, with no note and no warning attached.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 1, 'The audit splits every figure into computed, typed and held for literature. What separates the second class from the third?', '["A typed figure arrives as an input and a held one is a constant written into the module, so only the second of the two is ever visible in the source.", "A typed figure is a published chart or table the engine names the reference for; a held one is a figure the oracle cannot derive by any route at all.", "A typed figure has been checked against a published value and a held one is waiting for the publication to arrive.", "A typed figure moves the answer and a held one cannot, which is why nothing graded in this course reads a held figure."]'::jsonb, 1, 'Both are figures nothing here derives, and the difference is what is claimed about them. Kb, Kw and KSH are inputs by design with their references named, while the Kv fit is a fit no route in this package could reproduce.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 2, 'Which set is the typed one on this engine?', '["The pool fire constants 21000.000000000000 and 34500.000000000000 with the exponent 0.820000000000.", "The Kv viscosity fit and the sphere-drag correlation with its low-Reynolds cap of 240.000000000000.", "The Napier boundaries 1500.000000000007 psia and 3200.000000000003 psia, and the customary intensities.", "Kb for gas, Kw for liquid, KSH for steam, and the API 526 orifice table of 14 rows."]'::jsonb, 3, 'The typed set is short and every member of it is a published chart or table taken as an input. The other three groups named here are all held for literature, which is a different status and gets a different sentence.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 3, 'What is the difference between an oracle that is an independent derivation and one that is a transcription?', '["An independent derivation goes red when the engine moves, because two derivations disagree; a transcription cannot, because there is only one derivation in the room.", "An independent derivation is written in SI and a transcription in USC, so a packaging error is what separates them.", "An independent derivation is run against the published rows and a transcription against the engine, so only one is regenerated.", "An independent derivation covers every route and a transcription covers only the routes the published set already reaches."]'::jsonb, 0, 'That test is what the audit table applies route by route. The march is checked against the same march solved in closed form in SI, the wetted area against a polyline round the real circle, and the point source against a quadrature of the sphere.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 4, 'The pool fire pair is held for literature, yet the oracle does check something about it. What?', '["The exponent of 0.820000000000, which falls straight out of the log ratio of two duties taken at 100 and at 1000 ft2 respectively.", "The credit between the two constants, which the digest measures as a drainage factor of 1.642857142857.", "The unit packaging, by checking the USC pair against the published SI pair with the exponent carried through the conversion.", "The physics, since the same duty comes back from a second correlation the oracle carries in SI."]'::jsonb, 2, 'A packaging error would be caught even though the constants themselves are not in question. That is a hedge on a held figure rather than a check of it, and the audit column says which it is.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 5, 'The audit puts the 25 ft wetted-height limit in none of its three columns. What is it instead?', '["It is a published boundary, so the suite pins it as a behaviour of the engine and it is unable to move without the suite going red on it.", "It is an empirical fit that the oracle shares on purpose, so moving the figure in both files at once leaves the whole published set green.", "It is a stated convention of this engine, and it is exported beside its own unclamped form so that the effect of it stays inspectable.", "It is a caller''s decision rather than a constant, since it depends on a plot elevation the engine is never told."]'::jsonb, 3, 'It arrives as a note on every duty rather than as arithmetic: wetted area counts only to 25 ft above grade, and the truncation is the caller''s to apply before calling.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 6, 'Move the Kv fit coefficients in both the engine and its oracle and every published case still passes. How should that result be reported?', '["As a tolerance problem, since the published rows are checked loosely enough for the change to hide inside them.", "As the finding itself. A gate that stays green while the thing it guards has changed is not a gate, and the only honest response is to say so where a reader will look.", "As a missing case, since the fit has no published row placed where its coefficients are worth anything.", "As a reassurance, since agreement across the whole published set is what a validation suite exists to produce."]'::jsonb, 1, 'The same holds for the sphere-drag correlation. Both are shared between the engine and its oracle on purpose, because no route here can derive either, and nothing graded in this course rests on either of them.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 7, 'The published set places a liquid case at a Reynolds number of 92.428866. What can that case discriminate, given that the fit it sits on is shared with the oracle?', '["The fit coefficients themselves, since the term table prints what each is worth at that Reynolds number.", "The clamp at one, which would show up first at a low Reynolds number.", "Engine-side drift, since it sits where the inverse-three-halves term is still worth something.", "Nothing at all, since a shared fit leaves every case on that route unable to tell anything apart."]'::jsonb, 2, 'A case can be worth something for one purpose and nothing for another. A change in how the engine uses the fit shows up at that row, while a change to the fit itself, made in both files, does not.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 8, 'The Napier fit has published cases at 2014.700000, 3100.000000 and 1550.000000 psia. What is that placement for?', '["So the two boundaries at 1500.000000000007 and 3200.000000000003 psia are each covered by a case beside them.", "So the correction is sampled once below the threshold, once inside the enlarging band and once above the range.", "So the published set carries a row at each pressure the steam equation changes its leading constant at.", "So the constant is checked where moving it by a realistic amount moves the answer by more than the tolerance."]'::jsonb, 3, 'A case can be present and unable to discriminate its own constant, which is a different fault from a missing case. The test is arithmetic: move the constant a realistic amount and ask whether the answer moves by more than the tolerance the case is checked at.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 9, 'Three different balanced-bellows factors in the subcritical branch all return 2.658695041098 in2, to twelve decimals. What is that?', '["Correct behaviour, because the standard uses F2 in that branch and the bellows factor has no place in it.", "A defect of the kind the audit describes, since a validated input with a box has no effect on the answer.", "A coincidence of the stated case, since the three factors chosen happen to fall inside one printing precision.", "A clamp, since the engine holds the factor at one whenever its branch is not in use."]'::jsonb, 0, 'What makes it teachable rather than confusing is that the engine says so: the call succeeds and attaches `subcritical flow uses F2 in place of Kb, so the typed Kb was ignored`. Silence would have left a user turning a dial and inventing an explanation.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 10, 'The steam superheat factor at 1.000000 gives 0.949984 in2 and at 0.830000 gives 1.144559 in2, a ratio of 1.204819277108 against a factor ratio of 1.204819277108. What does that pair of ratios say?', '["The factor is applied twice, since the area ratio and the factor ratio are equal rather than squared.", "The factor is clamped at one, since only the smaller value moved the area.", "The factor divides straight into the area, so this input always moves the answer exactly.", "The factor is computed rather than typed, since the engine reproduces the ratio to twelve decimals."]'::jsonb, 2, 'Put it beside the bellows factor in the subcritical branch, which never moves its answer and is right not to. The two are read completely differently, and the first question to ask of any input is which kind it is.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 11, 'Walk an input across its whole declared range, print the spread of the answer and compare it with the precision the answer prints at. Which outcome is the one to investigate?', '["A spread smaller than the precision with no reason offered, because the input asserts that it matters while doing nothing.", "A spread of exactly zero, because an input that cannot move an answer at all has no business being validated.", "A spread much larger than the precision, because an input that dominates an answer usually hides a second effect.", "A spread that changes direction inside the range, because a non-monotonic answer means two effects are being confused."]'::jsonb, 0, 'A spread of zero with a stated reason is the bellows factor in a branch that is not running. A large spread is an input doing its job, and the drum holdup is the worked example: the required length moves by tens of feet and the column is not even monotonic.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 12, 'The module has 22 exports, and 7 of them return a bare number and signal a refusal with NaN. Why do those 7 need separate care?', '["A bare NaN is returned only on a valid call, so an error check on those routes would reject good answers.", "A bare NaN passes an error check that looks for a property, so the number itself has to be tested.", "Those 7 are the tables and the derived constant, which carry no error key.", "A NaN from those routes is a warning, so the answer is still usable."]'::jsonb, 1, '12 of the exports return an object and keep the contract of either a finite result or an `error` string, 2 are published tables and 1 is a derived constant. A non-finite number with no error key is exactly what a caller''s guard cannot see.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 13, 'One rule covers Kd, Kb, Kc, Kw, KSH, the environment factor, the radiated fraction, the transmissivity and the blowdown discharge coefficient. What does it say?', '["A certified coefficient is a published chart value, so it must be typed rather than computed from anything.", "A certified coefficient is a fraction of an ideal, so it must be above zero and no more than one.", "A certified coefficient must be finite and the refusal names it, which is what makes nine messages into one rule.", "A certified coefficient always divides the answer, which is what makes nine messages into one single rule."]'::jsonb, 1, 'The refusal names the offender every time, and a rule that general beats memorising nine messages. It also says what the engine believes: a coefficient cannot add capacity, so a value above one is a typing error.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 14, 'A drainage answer arriving as a string is refused by name. What class of defect is that guard aimed at?', '["The gap between a screen and a function, where a select element sending a string would buy the drainage credit silently.", "A physics error, since a drained pool and an undrained one carry different constants and different exponents.", "A unit error, since a boolean sent as text cannot be checked against the environment factor beside it.", "A precision error, since a string compared against a boolean resolves differently at different printing precisions."]'::jsonb, 0, 'The string "false" is truthy in JavaScript, so the duty would come back on the drained constant with nothing said. The engine''s own wording is `adequate drainage must be the boolean true or false`.'),
  ('relief', 'advanced', 'module', 'm05-what-the-method-does-not-know', 15, 'Of the refusals this module can produce, exactly one carries a second key beside `error`. Which, and why does it matter?', '["blowdown past its time limit returns the orifice it would need, and a guard reading only the error discards it.", "gasVaporArea at a back pressure above the relieving pressure returns the ratio, which the caller needs to size a header.", "liquidArea below the certified envelope returns the correction it computed, which is the figure the warning refers to.", "selectOrifice past the largest returns `multipleOfT`, and a guard that stops at the error throws that figure away."]'::jsonb, 3, 'It is a whole number of valves, worked out by a refusal that then had to be read for it. 42 refusals run across 12 of the routes and every other one of them carries the error alone.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 1, 'This module is the one place in the course whose subject is what the engine used to do. Four other places carry the same history without a frame. Which are they?', '["The digest''s audit section, the published golden file, and the validation oracle''s header.", "The lesson exercises, the teaching lab, and the three explorer panels that are built on it.", "Engine comments, the wave''s recon and findings records, and the repair''s findings file.", "The refusal messages, the warning texts, and the notes the engine returns on a successful call."]'::jsonb, 2, 'All four are provenance. A sentence lifted out of one arrives with no frame around it, and nobody can frame what they did not know was history. Counted by reading the module, 12 comment lines carry the repair marker and 16 are written in a past tense about former behaviour.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 2, 'Before the repair, a first step that would have removed more mass than the vessel held broke the loop with the clock still at zero. What did the caller receive?', '["A time of zero seconds, the vessel still at its start pressure, and no error key at all.", "An error key naming the orifice, which the caller''s guard reported as a failed calculation.", "A time of zero seconds with a warning attached saying the first step had overrun the inventory.", "A non-finite time with no error key, which rendered on the screen as a blank depressuring field."]'::jsonb, 0, 'Every caller guard passed, and the screen printed a depressuring time of zero minutes under a hint saying that was inside the customary fifteen. Today those geometries march properly, because no step may remove more than a twentieth of the inventory.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 3, 'That former failure is kept as a general lesson rather than as an anecdote. What is the lesson?', '["A loop that exits early is the hardest defect to find, because the state it leaves behind looks like a converged one.", "A calculation that returns without an error key has failed its contract, whatever the number beside it happens to be.", "A study run to answer one question should never return a second quantity, because the second will be read as the first.", "The worst failure of a calculation is not a wrong number, it is a wrong number shaped like the answer somebody wanted."]'::jsonb, 3, 'A depressuring study asks whether a vessel is down inside the customary time, so the dangerous failure answers yes. A failure returning nothing gets investigated; a failure returning zero, where a small number is the good news, gets believed.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 4, 'What replaced that former behaviour, and where can you see it working today?', '["A refusal on any geometry whose first step the march cannot carry, which names the orifice as the input most likely at fault.", "A budget of a twentieth of the inventory on any step, and the three small-vessel cases that each reach their end pressure.", "A check on the returned time, which the engine now compares against the customary fifteen minutes before returning.", "A closed-form fallback for the first step, which the march takes over from once the inventory allows it."]'::jsonb, 1, '5.000000 ft3 through 4.000000 in, 100.000000 ft3 through 17.000000 in and 500.000000 ft3 through 38.000000 in each report 34 steps and 34 substeps, and each returns a time above zero.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 5, 'Before the repair the drum used one factor for both the vapour cross-section and the fall distance. What did a user turning the holdup box see?', '["The required length moving by less than a millionth of a millionth of a foot, while the vapour velocity beside it moved by a factor of ten.", "The required length moving by tens of feet, while the vapour velocity beside it stayed where it was.", "Both the length and the vapour velocity frozen, since the factor cancelled out of the whole calculation.", "The required length moving only above a holdup of one half, where the two factors stopped cancelling."]'::jsonb, 0, 'Two factors that cancel algebraically leave a box on a screen that a user will turn, watching nothing happen, and conclude the quantity does not matter. The input was also ambiguous, used once as an area fraction and once as a depth fraction.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 6, 'What is the test that finds a former defect of that kind, and what does it cost?', '["Plant a change in the constant sitting behind it and then regenerate the whole published set. One rebuild of the goldens.", "Compare the route against its oracle at both ends of the input''s declared range. Two runs and a ratio.", "Walk the input across its whole range at everything else fixed and print the spread of the answer. One sweep.", "Read the returned object for a field naming the input, since a live input is always echoed back. One call."]'::jsonb, 2, 'Compare the spread against the precision the answer prints at. The audit lesson on an input that changes nothing runs the same test on the repaired holdup, which moves the required length by tens of feet and is not even monotonic.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 7, 'What does the drum''s holdup input mean today?', '["The fraction of the cross-section the liquid occupies, which is what a segment area integral returns.", "The liquid level as a fraction of the diameter, which is what a level instrument reads.", "The fraction of the drum''s length given over to liquid holdup between the inlet and the outlet.", "The fraction of the vapour space left above the liquid, which is what the fall distance is measured across."]'::jsonb, 1, 'The vapour cross-section is then the exact circular segment above that level, and the engine returns the depth, the area fraction, the vapour area and the fall distance, so the convention is visible rather than inferred.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 8, 'Before the repair the blowdown mass flow multiplied the caller''s discharge coefficient by a second, hard-coded coefficient of its own. What did a caller see?', '["A typed value ignored entirely, with a warning saying the engine had substituted its own coefficient.", "A time that moved the wrong way as the coefficient was turned.", "A refusal whenever the product of the two coefficients went above one, which is the rule on a certified coefficient.", "A typed value running about two and a half percent low, so the time came out that much long."]'::jsonb, 3, 'The answer stayed plausible and it moved the right way when the coefficient was turned, and every case was wrong by the same factor. That is the one pattern a sanity check cannot see.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 9, 'Why can a constant applied twice not be found by inspecting an answer?', '["It moves every case smoothly by the same factor, so there is no case that looks wrong beside another.", "It only ever bites at the extreme ends of the declared range, where nobody thinks to run a sanity check anyway.", "It is absorbed into the printing precision, so the answer is identical at the decimals a reader sees.", "It cancels against itself over a full march, so only a single step could ever show it."]'::jsonb, 0, 'The way to find one is to rebuild the quantity from first principles and divide. A number applied twice is invisible on the answer and visible only in a ratio.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 10, 'What would catch that former defect today?', '["The refinement study, which would show the time failing to settle as the step is halved.", "The certified-coefficient rule, which refuses any coefficient above one on the way in.", "The closed-form comparison in the first module, with the ratio column reading one.", "The published rows, whose differences would have widened."]'::jsonb, 2, 'The marched time is compared against the exact integral of the same balance, built from the engine''s own gas coefficient, the recovered gas constant and the stated geometry. A discharge coefficient applied twice is one of the three faults that column can catch.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 11, 'Before the repair, twenty defects were planted one at a time in the engine. What did the published suite do?', '["It went red on every one, which is what showed the tolerances were far too tight to be useful.", "It stayed green on the three routes that had no published case, and went red on all the rest.", "It went red on seven and green on the thirteen where the defect sat inside a held figure.", "It stayed entirely green in seven of them, including an inverted division inside the drum''s own length equation."]'::jsonb, 3, 'Three whole routes had no published case and no oracle route at all, and five oracle routes were transcriptions of the engine rather than independent derivations. That last was proved by planting the same defect in both files and regenerating the published set.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 12, 'What is the reusable method inside that finding?', '["Count the published rows against the routes, since a route with fewer rows than inputs cannot be covered.", "Break the engine on purpose and watch. A suite that stays green has told you something about itself.", "Widen every tolerance until something fails, which locates the case that is carrying the whole block.", "Regenerate the published set from the engine and compare it against the committed one, row by row."]'::jsonb, 1, 'There are two separate ways a validation case can be worth nothing. It can be missing, so a route has no case at all, or it can be present and unable to discriminate, sitting where the constant it checks is worth less than the tolerance it is checked at.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 13, 'Where has that former state been left today?', '["The published set carries 11 blocks, the five transcriptions are independent derivations, and the two routes nothing can discriminate are named.", "Every route now has an independent oracle, so no published case in the set is unable to discriminate.", "The two shared routes were dropped from the published set, so nothing green in it is green for the wrong reason.", "The tolerances were tightened until the twenty planted defects all went red, which is the standing form of the check."]'::jsonb, 0, 'Naming the two is the honest statement of the limit. Sections 27 and 28 are the standing form of that lesson, about the engine as it is now, and nothing graded in this course rests on either of the two shared fits.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 14, 'The digest counts the history that sits in the engine source: 12 comment lines carrying the repair marker and 16 written in a past tense, in a module 619 lines long. What is that count for?', '["It measures how much of the repair is still outstanding, as a tally of lines yet to be cleared.", "It is the tally the copy-rule gate runs against every lesson body in this wave.", "It records how many of the repair findings were reachable by typing into the shipped studio.", "It puts a size on an unframed source, at roughly one line in 39 of the file."]'::jsonb, 3, 'Nothing gates a writer reading engine comments. A sibling wave shipped three repair-history sentences into committed lesson text and the worst of them came from a source comment.'),
  ('relief', 'advanced', 'module', 'm06-what-was-repaired-and-what-was-not', 15, 'This tier''s capstone asks for four readings from one blowdown call and two from the point source. Why does none of the six rest on a held figure?', '["The four blowdown fields are the accounting fields, which carry no constants at all, and the two radiation fields are pinned by the equality test.", "The march and the point source are the only two routes in the module with no held figure anywhere behind them.", "The blowdown answers are taken well above the returned choked floor with an empty warning field, and the radiation answers are stated as a release in kW against a project allowable.", "Every held figure in the module belongs to a sizing route, and no sizing route is read in this tier''s capstone."]'::jsonb, 2, 'Where a method has a stated limit, the cheapest way to a defensible number is to stay clear of the limit and show that you did. A distance beside a stated allowable is auditable; a distance beside an exposure label is not.'),
  ('relief', 'advanced', 'final', null, 1, 'A station of the AFIESERE trajectory at 100.000000 s reads 524.991018 psia and 451.589391 degR. What does a station carry, and what is missing from it?', '["A time, a pressure and a temperature. No mass, so an inventory profile cannot be read off the call.", "A time, a pressure and a mass. No temperature, which is reported only for the end state.", "A time and a pressure. No temperature at all, which the digest derives from the pressure ratio instead.", "A time, a pressure, a temperature and a mass, which is why the return needs 270 of them."]'::jsonb, 0, 'The march reports the mass at the two ends only, 3469.2925 lb and 648.7449 lb. Getting a quantity a route does not return means calling it repeatedly, which is how the end-pressure table was built.'),
  ('relief', 'advanced', 'final', null, 2, 'The digest compares the march against a closed form at the stated case, at a 2.0 in orifice, at a discharge coefficient of 0.60 and from 1800 psia. What is varied across those four rows, and what is not?', '["The isentropic exponent moves; the time stays inside the printing precision.", "The step size moves across the four; the closed-form time stays fixed because it does not use one.", "The geometry and the start pressure move; the ratio stays within a part in a million of one.", "The compressibility moves across the four; the marched time stays fixed because it holds it constant."]'::jsonb, 2, 'Four different cases agreeing with a second derivation is a stronger statement than one case doing so. A coefficient applied twice or an exponent off by one would move every row of the column together.'),
  ('relief', 'advanced', 'final', null, 3, 'With the compressibility held constant and the flow choked throughout, the mass balance becomes separable. What does that buy?', '["A closed form for the final temperature, which is why the orifice sweep returns one value across it.", "An exact integral for the time between two masses, because the rate of mass loss goes as the mass raised to (k+1)/2.", "A march that needs no step size, since the balance can be evaluated at the end state directly.", "A proof that the two model decisions are harmless, since the integral makes neither of them."]'::jsonb, 1, 'The closed form is built from the engine''s own gas coefficient, the gas constant recovered from the start mass, and the stated geometry. The validation oracle runs the same integral in SI.'),
  ('relief', 'advanced', 'final', null, 4, 'AFIESERE reports 2685 steps, 0 substeps, 270 stations and a time step of 0.100000 s. Which of those four is an input the route takes rather than something the march produced?', '["The station count.", "The step count.", "The subdivided count.", "The time step."]'::jsonb, 3, 'The other three are what the march did with it, and all three are returned so the run can be audited. A step of zero or a negative one is refused rather than accepted, because a march whose clock never advances can never reach its own time limit.'),
  ('relief', 'advanced', 'final', null, 5, 'The AFIESERE pressure falls from 1240.000000 psia to 1133.641018 psia over the first ten seconds and from 153.996263 psia to 145.000000 psia at the end. Why is the early fall the steeper one?', '["The step size is finer early in the march, so more mass leaves in the first printed interval.", "The compressibility is furthest from its stated value early on, which the march then corrects as it goes.", "The rate through a choked orifice scales with the upstream pressure, which is highest at the start.", "The temperature is highest early, and the mass rate through the throat rises with temperature."]'::jsonb, 2, 'The temperature column follows the pressure down for the same reason, since the temperature here is carried by the pressure through the isentropic relation and by nothing else.'),
  ('relief', 'advanced', 'final', null, 6, 'A blowdown discharge coefficient of 1.000000 returns 220.103588 s. What does a coefficient of one mean on this call?', '["The top of the range the engine allows, since a certified coefficient is a fraction of an ideal.", "A default the engine applies when the caller states nothing, which is why the time is the shortest of the three.", "An ideal nozzle, which the engine treats as a limiting case and flags with a warning on the return.", "A coefficient the march computes for itself from the isentropic exponent at that geometry."]'::jsonb, 0, 'It is the caller''s own figure at the top of the range the engine admits for it, and the march applies it once. The time at that value, 220.103588 s, is the shortest of the three the digest walks.'),
  ('relief', 'advanced', 'final', null, 7, 'At an orifice of 0.750000 in the march returns 745.608268 s, which is 12.426804 min. What does the engine make of that figure?', '["It compares it against the customary fifteen minutes and returns a passing flag on the result.", "It records the margin against fifteen minutes in the warning field and leaves the field empty otherwise.", "It rounds the figure to the customary limit''s own precision so that the two can be compared directly.", "Nothing. It returns the time and stops, and the comparison against any limit is the caller''s act."]'::jsonb, 3, 'The practical consequence is a discipline. Write the limit you are judging against, and where it came from, in the same place you write the time, because a bare time in a report looks exactly like a passing time.'),
  ('relief', 'advanced', 'final', null, 8, 'At an end pressure of 40.000000 psia the march runs 462.482817 s, ends at 257.134963 degR and has removed 0.931629 of the inventory. Which of the three is the answer a depressuring study went looking for?', '["The time, since the customary criterion is itself stated as a time and the other two are by-products of it.", "It depends on the question asked, and a study that quotes one of them should say which question it answered.", "The final temperature, since it is the only one of the three that the orifice cannot change.", "The fraction removed, since it is the only one of the three derived rather than returned."]'::jsonb, 1, 'A depressuring study is run for the clock and for the cold end, and a single march answers both. The fraction removed is derived from the two masses and is a third reading off the same run.'),
  ('relief', 'advanced', 'final', null, 9, 'The end-pressure table runs from 600.000000 psia down to 25.000000 psia against a choked floor of 26.758009 psia. Which is the deepest row still clear of that floor?', '["80.000000 psia, where the march runs 354.644554 s and ends at 299.234348 degR.", "25.000000 psia, where the march runs 540.397236 s and ends at 232.011700 degR.", "145.000000 psia, where the march runs 268.419002 s and ends at 340.807983 degR.", "40.000000 psia, where the march runs 462.482817 s and ends at 257.134963 degR."]'::jsonb, 3, 'The rows that cross the floor carry the engine''s own warning, and only the bottom row of this table does. An answer taken above the floor with an empty warning field does not rest on the choked assumption at all.'),
  ('relief', 'advanced', 'final', null, 10, 'On a relief valve a larger orifice is a larger answer to the same question. On a blowdown it is not. What does it change instead?', '["Only the clock, since the end state is already fixed by the two pressures and the exponent.", "Only the cold end, since a larger hole expands the gas faster and takes it further down.", "Both the clock and the cold end, in the same proportion, which is what the orifice sweep prints out.", "Only the step count, since the march adjusts its step to the rate the orifice permits."]'::jsonb, 0, 'That inversion is worth holding onto because it cuts against the intuition the Associate tier builds. Across eight orifices the digest counts the distinct final temperatures at 1.'),
  ('relief', 'advanced', 'final', null, 11, 'An orifice of 0.500000 in gives 1677.618587 s, which is 27.960310 min, over 16777 steps. Which of those three figures would a reviewer challenge first?', '["The step count, because a count that large means the march has spent its budget on this row.", "The minutes, because the conversion is the digest''s arithmetic rather than an engine return.", "The time, because it is the reading the study rests on and it carries every stated input with it.", "None of the three, because all three of them come back from the same call and stand or fall together."]'::jsonb, 2, 'The curve is a property of the vessel and the assumptions together. Move the volume, either pressure, the gas properties, the discharge coefficient or the step and the whole curve moves with it.'),
  ('relief', 'advanced', 'final', null, 12, 'A published row of 500.000000 ft3 from 1014.700000 psia to 114.700000 psia through 1.000000 in at a discharge coefficient of 0.850000 carries 268.353614 s, against the engine''s 268.068607 s, a relative difference of 1.062e-3. What is that difference?', '["The tolerance the published row is checked at, which the engine is required to stay inside.", "A unit packaging error between the USC march and the SI oracle, carried through the conversion.", "Step error in the march, measured against an oracle that solves the same balance in closed form in SI.", "Drift since the golden file was first cut, which is what a re-run of the published inputs exists to catch."]'::jsonb, 2, 'A march and a closed-form integral have almost nothing in common as computations, and they land about a thousandth apart for a reason you can name and measure. That is a result, and a shared fit reproducing itself perfectly is not.'),
  ('relief', 'advanced', 'final', null, 13, 'Two of the five published blowdown rows carry a relative difference of 2.654e-4 and the other three sit near 1.062e-3. Which two are the tighter pair?', '["The two rows at 500.000000 ft3 through 1.000000 in and through 2.000000 in.", "The 2000.000000 ft3 row through 1.500000 in and the 5.000000 ft3 row through 4.000000 in.", "The two rows whose discharge coefficient is 0.850000 rather than 0.800000.", "The 5.000000 ft3 row through 4.000000 in and the 500.000000 ft3 row through 38.000000 in."]'::jsonb, 3, 'Those are two of the three small-vessel and large-orifice geometries the step study runs, where every step is subdivided. A published set without them cannot discriminate a march that stops before it starts.'),
  ('relief', 'advanced', 'final', null, 14, 'Four published rows finish at 338.611469 degR and one at 405.931108 degR. What sets that apart?', '["That row uses a larger orifice, and a larger orifice takes the vessel further down before it stops.", "That row states a different start temperature, a different pair of pressures and a different isentropic exponent.", "That row is the one whose relative difference is 2.654e-4 rather than 1.062e-3, at a finer effective step.", "That row holds a different compressibility, which is the only one of the stated inputs the end state reads."]'::jsonb, 1, 'The end state follows from the pressure ratio across the blowdown, the start temperature and the exponent. The four rows that agree are the four given the same three figures.'),
  ('relief', 'advanced', 'final', null, 15, 'Of the fields a blowdown call returns, which is an accounting field rather than part of the answer?', '["The mass remaining at the end of the march.", "The final pressure the march actually reached.", "The trajectory of stations the march returned.", "The number of steps that had to be subdivided."]'::jsonb, 3, 'Six of the eleven fields are the answer, four are the account and the eleventh is the warning slot. The account is the step size, the step count, the subdivided count and the pressure below which the choked assumption stops holding.'),
  ('relief', 'advanced', 'final', null, 16, 'Two columns of the refinement study never move: the substeps and the final temperature. Do those absences mean the same thing?', '["Yes. Both say the march is converged, which is what a column that holds still across a refinement means.", "Yes. Both are fixed by the two pressures and the exponent, and the step size enters neither of them.", "No. The budget never bit at these geometries, while refinement could not have moved the temperature at all.", "No. The substeps are fixed by the end pressure, while the temperature is fixed by the step size."]'::jsonb, 2, 'A convergence table with several columns looks like a convergence statement about all of them. It is only a statement about the columns that moved, and reading a constant column as confirmation is reading an absence of evidence as evidence.'),
  ('relief', 'advanced', 'final', null, 17, 'Across the sixty-four-fold refinement the time moves by 0.002015907907 s in total, and the digest prints a time to six decimals. What does setting one beside the other show?', '["That the step shows in a printed time, since the movement is thousands of half-units in the sixth decimal.", "That the step has dropped out of every printed time, since the whole movement sits below the sixth decimal.", "That the engine returns its time at six decimals, so any movement smaller than that cannot be represented at all.", "That the march has not converged, since a converged march stops moving at the precision a time prints at."]'::jsonb, 0, 'A time prints to six decimals and the movement is 4031.815814 times half a unit in that sixth decimal, so the step is visible in the printed figure and belongs beside it. The march has still converged in its own terms, and whether it is marching the right balance is the closed-form comparison''s question.'),
  ('relief', 'advanced', 'final', null, 18, 'What would you compare on any march to find out whether it quantises its answer to one step?', '["The time it reports against the same run at half the step, which doubles if the answer is quantised.", "The final pressure it reports against the pressure you asked for, at full precision.", "The step count against the station count, since a quantised march returns one station per step.", "The final temperature against the isentropic end state, which a quantised march overshoots."]'::jsonb, 1, 'A route that hands the target back to you rather than what it reached has hidden the question instead of answering it, so the comparison has to be made at full precision rather than at the precision the figure is printed to.'),
  ('relief', 'advanced', 'final', null, 19, 'A march subdivides a step that would remove more than a twentieth of the inventory. What does it hand back so that you can see it happened?', '["A warning on the return, which names the geometry as the reason for the subdivision.", "The finest step it fell back on, which replaces the step size the caller stated.", "A flag on each affected station of the trajectory, so the subdivided interval can be located.", "The count of steps it subdivided, beside the count of steps it took."]'::jsonb, 3, 'A non-zero count is not a fault. It is the budget working, and it tells you the geometry sits in the corner where a fixed step struggles, which is worth knowing before you quote the time.'),
  ('relief', 'advanced', 'final', null, 20, 'Why can a validation case chosen because it is extreme fail in a way a typical case cannot?', '["It sits outside the tolerance band, so any movement shows.", "It runs the march at its finest effective step, where the step error is smallest and visible.", "It is chosen against a known failure mode, so a failure on it names what went wrong.", "It is the only kind of case an independent oracle can be written for, so it alone can go red."]'::jsonb, 2, 'The three hardest geometries in this study each report 34 steps and 34 substeps and each reaches its end pressure with a time above zero. Put the hardest geometry in a set deliberately, and put it there because you know what it is hard for.'),
  ('relief', 'advanced', 'final', null, 21, 'The heat release of 1193971.5392 kW is derived from a stated rate and a stated heating value. Suppose the heating value were wrong. Where would that show?', '["In every intensity and every distance this flare produces, with nothing in the package able to notice it.", "In the transmissivity, which the engine would then have to carry the whole of the error in.", "In the refusal the route raises on a release outside the range a flare of that size can reach.", "In the round trip between the two directions, which would stop closing at a ratio of 1.000000000000."]'::jsonb, 0, 'The engine takes a heat release in kW and knows nothing about rates or heating values, so that arithmetic is the caller''s and the caller owns any error in it. A round trip would close perfectly on a wrong release, because the same figure goes into both directions.'),
  ('relief', 'advanced', 'final', null, 22, 'The stated flare gives 1.427138 kW/m2 at a transmissivity of 0.920000 and 1.551237 kW/m2 at 1.000000, with everything else held. Which way has the change moved the answer, and why?', '["Downward, because a higher transmissivity spreads the same release over more of the sphere before it arrives.", "Upward, because a transmissivity of one lets all of the radiation across the air between the flame and the receiver.", "Upward, because the engine treats a transmissivity of one as a signal to drop the radiated fraction from the relation entirely.", "Neither way on its own, because the transmissivity and the radiated fraction are applied as a product and only their product moves the result."]'::jsonb, 1, 'Both are fractions and both multiply the release that reaches the receiver, so raising either raises the intensity. The engine validates each of them as a coefficient that cannot add capacity, above zero and no more than one.'),
  ('relief', 'advanced', 'final', null, 23, 'Suppose the test asserting the two allowable-intensity tables stay equal did not exist. What would a learner be exposed to?', '["Two different sets of values for one published table, one of which would be wrong.", "A table with no source at all, since the assertion is what stands in for a reference here.", "Two sets of words for one published table, met in two different studios.", "A graded answer resting on a held figure, since nothing else keeps the table out of the answer key."]'::jsonb, 2, 'The test stops the two copies drifting apart, which makes a change to either a reviewed act rather than a quiet one. It does not make either copy right, because it compares them to each other and to nothing else.'),
  ('relief', 'advanced', 'final', null, 24, 'This course carries a point-source model and a route that returns a distance, and computes no setback at all. What does it teach in place of one?', '["That the point source is a screening model and a setback needs a solid-flame one instead.", "That a setback cannot be computed without a flame height, which this engine has no route for.", "That the four customary intensities are held, so no distance solved against one may be reported.", "That the relief engine holds a second copy of one model, and what keeps the two copies the same."]'::jsonb, 3, 'Two engines in one package holding the same screening relation is a fact about the package rather than about flare radiation, and it raises a question a single copy never would.'),
  ('relief', 'advanced', 'final', null, 25, 'The published radiation rows and the published setback rows are re-run together in the audit. What do the two blocks establish between them?', '["That both directions of the same relation agree with an oracle built from a quadrature and a bisection on it.", "That the forward route is checked and the inverse inherits that check through the round trip.", "That the four customary intensities are correct, since the setback rows solve against two of them.", "That the relation is exact, since both blocks agree to the last bits double precision holds."]'::jsonb, 0, 'A published row at 12000.0000 kW and 35.000000 m gives 0.175395 kW/m2, and one at 6.310000 kW/m2 gives 5.835288 m. Agreement at the size of rounding is the expected outcome when a quadrature and a closed form are two roads to the same sphere.'),
  ('relief', 'advanced', 'final', null, 26, 'Which four inputs does the forward radiation route take?', '["A heat release, a distance, an allowable intensity and a transmissivity.", "A heat release, a distance, a radiated fraction and a transmissivity.", "A relief rate, a heating value, a radiated fraction and a distance.", "A heat release, a flame height, a radiated fraction and a transmissivity."]'::jsonb, 1, 'The inverse takes the same four with an allowable intensity in place of the distance, and refuses the same bad ones. Checking that an inverse validates as much as its forward route is a cheap test with a real failure mode behind it.'),
  ('relief', 'advanced', 'final', null, 27, 'Each of the 42 refusals in the audit is run as one bad input with everything else sound. Why that way?', '["So the refusal order inside each route can be read straight off the rows, which is what a caller needs.", "So every route reaches the same number of refusals, which is what makes the count comparable.", "So a refusal cannot be reached by two bad inputs at once, which would leave the message ambiguous.", "So the message and the input that caused it sit on the same row and neither has to be inferred."]'::jsonb, 3, 'The build asserts every row too: a row labelled a refusal whose call had succeeded would print success fields under a refusal heading, and no numeric sweep can see that.'),
  ('relief', 'advanced', 'final', null, 28, 'Six warnings are run and printed in the audit. How should that figure be read?', '["As the total the module can produce, since the audit enumerates the module''s whole warning surface.", "As the number that fire on the teaching streams, since a warning outside them is not printed.", "As the number exercised, since a count of every condition a module can reach is a claim somebody has to check.", "As the number of routes carrying a warning, since each of the six belongs to a different route."]'::jsonb, 2, 'A warning comes with a usable answer and flags a condition, which is read differently from a refusal, which returns no answer, and from a note, which names a decision left to the caller.'),
  ('relief', 'advanced', 'final', null, 29, 'The audit prints a drum call at 5.000000 ft on the same duty and records the note as none. What is that row doing?', '["Showing that the note is a judgment with edges rather than something attached to every call.", "Showing that a drum that small refuses, so no note can be attached to the result.", "Showing that a note is suppressed whenever the L over D falls below the go-wider edge of the band.", "Showing that the engine leaves no note when a warning is present on the same call."]'::jsonb, 0, 'The go-wider note starts at an L over D of 6.000000000000 and the smaller-drum note ends at 2.000000000000. Between those two the engine says nothing, which is the band it treats as reasonable.'),
  ('relief', 'advanced', 'final', null, 30, 'Two figures in this module are held with no pin, no partial check and no unit conversion standing in for the physics. Which two?', '["The Napier boundaries and the four customary allowable intensities with their labels.", "The Kv viscosity fit''s coefficients and the sphere-drag correlation.", "The pool fire constants with their exponent and the 25 ft wetted-height limit.", "The API 526 orifice table and the balanced-bellows factor Kb for gas."]'::jsonb, 1, 'The Napier boundaries are pinned as behaviour, the pool fire pair is hedged by a unit check, and the 25 ft limit is a caller''s decision rather than a constant. Those two are held with nothing behind them at all.'),
  ('relief', 'advanced', 'final', null, 31, 'The crossing back through unity at 1580.310880829016 psia is both derived by the engine and exported by it. Which class does the audit put it in?', '["Computed, because it falls out of the fit that the oracle checks.", "Typed, because it is a published boundary the engine takes as an input and names.", "Held for literature, because it sits between two boundaries nothing in the package derives.", "A stated convention, because exporting a figure is what makes it a decision of this engine."]'::jsonb, 0, 'The threshold at 1500.000000000007 psia and the top of the range at 3200.000000000003 psia are the held pair, pinned by the suite as behaviour. The crossing between them is arithmetic on a fit, which is a different status.'),
  ('relief', 'advanced', 'final', null, 32, 'The unclamped viscosity fit is exported alongside the clamped one, and it reaches 1.006542523506. Why export the unclamped form at all?', '["So a caller can choose which of the two to apply, since the clamp is a convention rather than a rule.", "So the oracle has a route to the fit that is independent of the engine''s own clamped one.", "So the published set can place a case above the clamp, where the fit is worth the most.", "So the asymptote stays inspectable, which is what a stated convention owes a reader."]'::jsonb, 3, 'The clamp at one is a stated convention of this engine and the suite pins it. A correction for viscous drag that ran above one would be adding capacity, which is what the clamp prevents and what the export lets you see.'),
  ('relief', 'advanced', 'final', null, 33, 'The internal time limit of 7199.999985603571 s was bisected out of the engine''s behaviour rather than read off a constant. What does that buy?', '["A figure at twelve decimals, which is the precision a measured constant prints at.", "A figure the oracle can check, since a bisected edge is an independent derivation of it.", "A figure that describes what the engine does rather than what its source says.", "A figure the caller can override, since a measured limit is an input."]'::jsonb, 2, 'Every threshold in the audit is measured the same way, by asking the engine a question whose answer is that edge and nothing else. Where a constant is not exported, this digest measures it and says which question it asked.'),
  ('relief', 'advanced', 'final', null, 34, 'A refusal, a warning and a note are three different things this module returns. What separates them?', '["A refusal and a warning both return an answer, and only a note withholds one until the caller acts.", "A refusal returns no answer, a warning comes with a usable one, and a note names a decision left to you.", "A refusal names an input, a warning names a route, and a note names the section of the standard behind it.", "A refusal stops the call, a warning stops the march, and a note stops the answer being graded."]'::jsonb, 1, 'Read them in that order of severity. The clearest note is the one on the fire duty, where the engine cannot know the plot elevation and so states the rule and hands the truncation back.'),
  ('relief', 'advanced', 'final', null, 35, 'One section of the digest has former behaviour as its subject, and nothing follows it. What is the reason for that placement?', '["Every sentence above it is about the engine as it ships, so the boundary is visible to a reader.", "The section is the newest and was appended when the repair landed, so it sits where it was added.", "The material is ordered by tier, and the reading module of the last tier is the final one.", "A digest ends with its provenance, and the repair record is the provenance of this one."]'::jsonb, 0, 'A sentence about former behaviour that reads as current behaviour is a defect, and the frame for that material is its heading and its opening paragraph. Everywhere else in this course, such a sentence would be the defect.'),
  ('relief', 'advanced', 'final', null, 36, 'Before the repair, three whole routes had no published case and no oracle route at all. Which kind of empty gate is that?', '["A transcribed one, where the checking side is reading the same derivation as the engine.", "A shared one, where the constant under test sits in both of the files and moves in both at once.", "A slack one, where the tolerance is wider than the movement that a realistic defect would produce.", "A missing one, which is a different fault from a case that is present and cannot discriminate."]'::jsonb, 3, 'A route with no case at all is the easier fault to see and the easier to repair: write the case. The harder one is a case that exists, runs and passes while the figure under it moves, which is why the audit names its two.'),
  ('relief', 'advanced', 'final', null, 37, 'Which of these would be a defect if it appeared in a lesson of this course outside this one module?', '["A refusal message quoted verbatim inside backticks as the engine''s own wording.", "A sentence about former behaviour that reads as current behaviour.", "A figure quoted at the precision the digest prints that quantity class at.", "A statement that a figure is held for literature and is never graded here."]'::jsonb, 1, 'Framing comes from the heading above a passage or the line immediately before it. This module carries the frame in its own title and in its opening paragraph, and nothing in the course after it describes a former state.'),
  ('relief', 'advanced', 'final', null, 38, 'Four habits close this tier and none of them is about relief valves. Which is the one about agreement?', '["When two things agree, ask how many decimals they agreed to.", "When two things agree, ask how independent they were before they were compared.", "When two things agree, ask which of the two was written first and check the later one.", "When two things agree, ask whether the tolerance they were compared at could admit a defect."]'::jsonb, 1, 'Exact agreement between an engine and a copy of itself is the weakest result on offer. The other three habits are to ask what a number rests on, to measure a constant out of behaviour, and to walk an input across its range.'),
  ('relief', 'advanced', 'final', null, 39, 'This course stops deliberately at five boundaries. Which subject does it hand to the Flow Assurance course?', '["Cooldown and no-touch time.", "The flare setback and the customary allowable intensities.", "Critical against subcritical flow through a port.", "What a flare knockout drum is for."]'::jsonb, 0, 'That course names no depressurisation as its own scope exclusion, which is the one place the live catalogue points at this one. A final temperature is a gas temperature at the end of an adiabatic expansion, and the metal is a different model.'),
  ('relief', 'advanced', 'final', null, 40, 'The capstone asks for a figure to be recorded at the precision its quantity class prints at. What is the reason given?', '["A tighter figure would fail the tolerance, which is derived from the class rather than stated.", "The engine returns at that precision, so anything else is a figure it never produced.", "The published cases are checked at that precision, so an answer must match them to be gradeable.", "Rounding further is a different answer, and a grader and a reader cannot then disagree about what a correct reading is worth."]'::jsonb, 3, 'A time, a temperature, a pressure, an intensity and a distance print to six decimals, and a mass to four. The other half of the method is to say, of every figure handed in, whether the engine computed it, typed it, or holds it for literature.'),
  ('relief', 'advanced', 'final', null, 41, 'What did the Expert tier add to a course whose thesis is that the engine never chooses the case?', '["The question of which correction the engine computed and which one somebody had copied off a chart.", "The question of whether anything in the package would notice if a number an answer rests on moved.", "The question of what a stated fraction is a fraction of, which the drum and the segment both settle.", "The question of which scenario governs, which the fire case answers from geometry."]'::jsonb, 1, 'For most of this engine the answer is yes and the digest names the route that would notice. For the viscosity fit and the sphere-drag correlation the answer is no, and the digest names those too.'),
  ('relief', 'advanced', 'final', null, 42, 'A limit that has been located, written down and kept out of everything graded is treated here as acceptable. Why?', '["Because a limit kept out of the answer key cannot affect any figure the engine returns.", "Because a limit named in the audit is one the validation oracle has an independent route to.", "Because an unlocated limit is the dangerous kind, and naming one is what stops a reader resting on it.", "Because a limit that has been written down is one the published set has a case placed against."]'::jsonb, 2, 'Move either shared fit in both files and every published case still passes. The honest response is to say so where a reader will look, and then to keep every answer key clear of both.');
